-- GENERATED by `wfj generate` from data/gossip/gossip-7c.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7c0250378ca1b1c7"] = { "Non combattete più per voi stessi, vermi! Ora combattete per la Regina, quindi mostratemi qualcosa che sia degno di lei!", "." },
  ["7c04671c3165b2ac"] = { "Ecco. Ho finito la tua tonaca, {name}.", "." },
  ["7c0635998ff2ce60"] = { "Il prospettore è vivo?", "." },
  ["7c0cc604fd01a113"] = { "Avevi ragione, Fairbanks. È tragico.", "." },
  ["7c10c002093f0a77"] = { "Certamente, <signore/signorina>. Un tempo eravamo servitori della casata Barov: quella che oggi è nota come Scholomance.\n\nIo ero la governante e Lucien era il maggiordomo di padron Barov.\n\nAvevamo lavorato per i Barov per decenni, finché...\n\n<Eva piange.>", "." },
  ["7c1b6ff4f915b6fc"] = { "Cosa puoi dirmi sulla situazione dell'High Order?", "." },
  ["7c1b716564b26b20"] = { "Maywiki, ho perso il mio talismano e me ne serve uno nuovo.", "." },
  ["7c258328e4d48f8e"] = { "Accetto la tua offerta, Eitrigg.", "." },
  ["7c279e046295b09d"] = { "Ebbene, a quanto pare abbiamo un po' di tempo libero. L'⟦Horde=Orda⟧ ha completato i suoi compiti di raccolta, e si sta preparando tutto per la spedizione finale verso ⟦Silithus=Silitus⟧. Aspettiamo solo che l'⟦Alliance=Alleanza⟧ finisca i suoi. Dovresti andare a chiedere a quel loro sciocco ambasciatorino a che punto sono.", "." },
  ["7c36ccdfb7cf9599"] = { "Salute, {class}. Spero che tu mi porti buone notizie sull'evento Worldwide Invitational. Se è così, di certo ti hanno dato un codice segreto da riferirmi. In cambio del tuo codice ti regalerò uno dei cuccioli di panda di cui mi prendo cura.\n\nSussurramelo all'orecchio quando vuoi.", "." },
  ["7c3e7aa7f70c8a6a"] = { "La foresta trema e si scuote! I venti ululano! Si avvicina il Signore della Foresta?", "." },
  ["7c4251a50ed89cba"] = { "Che vuoi?", "." },
  ["7c436da41b77260b"] = { "Ahhh, allora sei <pronto/pronta>...\n\nMetterò la mia roba nel braciere, allora, e potrai parlare con lo spirito anche tu.\n\nE non preoccuparti pe' niente di vedere nel mondo degli spiriti col sapta... il vecchio Tiev conosce un trucco o due su come funziona la magia del sapta.\n\nSu, vieni giù al santuario con me e parliamo insieme agli spiriti, <fratello/sorella>.", "." },
  ["7c4820430477c8d1"] = { "{name}, è bello vedere veterani come te sul campo! Mi spiace riferirti che al momento le nostre scorte sono troppo scarse per lanciare grandi assalti di terra contro l'⟦Horde=Orda⟧.\n\nParla con il nostro intendente: ha delle missioni di rifornimento disponibili.", "." },
  ["7c4e3e7055a41dfa"] = { "Sidney è in ritardo. Pensavo che a quest'ora sarebbe già stato a casa.", "." },
  ["7c6445af1c30858e"] = { "{name} in arrivo, e veloce! Pronti a combattere!", "." },
  ["7c6ea0467ed113bd"] = { "Vieni giù al santuario con Tiev. Lì metteremo all'opera la magia dei sapta.", "." },
  ["7c6edaf46f72278d"] = { "Te l'avevo detto che avevi il sangue del fabbro, e avevo ragione. Va' a ⟦Ironforge=Forgiardente⟧, alla ⟦Great Forge=Grande Forgia⟧, e cercati un fabbro nanico di nome Bengus Deepforge. È stato il mio maestro, ed è uno dei più grandi fabbri che abbia mai conosciuto.", "." },
  ["7c71093c08857ed4"] = { "Cerca Tarshaw Jaggedscar nella caserma, sul lato est della città.", "." },
  ["7c757fcf5aa765dc"] = { "Dei $1998w lingotti di rame che ci servono, ne abbiamo $2018w. Per i lingotti di stagno siamo a $2005w su $2006w necessari. E sono stati fusi $2008w lingotti di mithril su $2009w per la causa.", "." },
  ["7c79582296214901"] = { "Un'interessante piega degli eventi.", "." },
  ["7c8302dd13f153a1"] = { "$964w, giovane {class}.", "." },
  ["7c85f12cf9a46be5"] = { "Ahimè, {class}, non sei <considerato/considerata> <osannato/osannata> presso Darnassus e gli elfi della notte di Teldrassil. Solo quando ci darai prova di te con le azioni, e non con semplici parole, metterò a tua disposizione la mia selezione di cavalcature.", "." },
  ["7c961f7154360fb2"] = { "L'⟦Horde=Orda⟧ ha conquistato le stalle!", "." },
  ["7ca1d6a8ed27330a"] = { "Non penserai davvero di farla franca con questa incursione. Verranno a prendermi, e pagherai per la tua insolenza.", "." },
  ["7cac39bbffb8128e"] = { "È... come deve essere.", "." },
  ["7caf7f53ce2f076b"] = { "<Avventuriero/Avventuriera>! Il ponte di vento che porta all'altra guglia è instabile. Forse dovrai aspettare qui con me finché non ritorna.", "." },
  ["7cb1aa2cfba5c3dc"] = { "Vuoi un volo per ⟦Rut'theran Village=Rut'theran⟧, offerto dal ⟦Cenarion Circle=Circolo Cenariano⟧?", "." },
  ["7cb2135bd7cc042a"] = { "Per quanto si impari, c'è sempre altro da sapere.", "." },
  ["7cb3a348d9d08b52"] = { "%s attira a sé il potere...", "." },
  ["7cb509bf41b0d4d8"] = { "Quegli altri ogre so' stati stupidi ad attaccarti, capo! Per questo io respiro ancora: io ho cervello e roba così!", "." },
  ["7cb88a256edffe8e"] = { "Ehi, non c'è niente che possa insegnarti, {name}. Fai due chiacchiere con Tally Berryfizz, laggiù. Arriva a malapena ai tavoli, ma quando si mette a preparare una pozione, attenzione!", "." },
  ["7cb8e32a5d3da75e"] = { "Ora la corruzione è in me.", "." },
  ["7cbd378b0dec4480"] = { "Al lavoro, feccia!", "." },
  ["7ccfe7d0596f8e49"] = { "Avremo anche patito la siccità, ma la carne non manca! Vuoi dare un'occhiata alla mia merce?", "." },
  ["7cd26e414511cc60"] = { "Ah, l'eterna ossessione per la ricchezza materiale. Beh, la fortuna ti sorride: la casa d'aste si trova nella Tradesman's Terrace.", "." },
  ["7cd61ae8dcdfab2f"] = { "Se volete scusarmi, devo congedarmi. Buona giornata, signore.", "." },
  ["7cd99c06529c6a1c"] = { "Morte agli uomini del Custode!", "." },
  ["7cdec4dfd5364047"] = { "Dea, concedimi il potere di sconfiggere i miei nemici! Ascoltami, ti prego: il mio bisogno è disperato e la mia causa è giusta!", "." },
  ["7ce07c70781762de"] = { "Il ⟦Stonehearth Graveyard=Cimitero di Cordipietra⟧ si trova a est dell'⟦Stonehearth Outpost=Avamposto di Cordipietra⟧, nel ⟦Field of Strife=Pian della Discordia⟧.\n\nAl momento nessuna delle due parti lo controlla.", "." },
  ["7ce337d40c7d3f22"] = { "Il nostro bottino del Grande Inverno non finirà a <un/una> {class} da strapazzo! Prendeteli!", "." },
  ["7cf36da6f7c39064"] = { "Unità esperte stanno entrando in battaglia!", "." },
  ["7cf63088e9e9c1a3"] = { "Mostrate forza al nemico, e prevarremo!", "." },
})
